contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use recipient as the target address for the bonus.
    // amount is not used because C's functions don't accept Ether on getFirstWithdrawalBonus,
    // but withdrawReward sends Ether out of C to recipient. Our contract can act as recipient
    // via its address when calling c.getFirstWithdrawalBonus(address(this)).
    function run(address recipient) public payable {
        require(recipient == address(this) || recipient != address(0));

        // Read observable before-state: contract balance and claimedBonus via effects.
        uint beforeBalance = address(c).balance;

        // Try calling getFirstWithdrawalBonus and capture whether it reverted.
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // If the call reverted, nothing else guaranteed by this test besides that revert flag.
        // If it did not revert and the recipient equals this contract, we expect C to have attempted
        // to withdraw 100 to recipient, so its balance should decrease by 100 and the second
        // call must revert (because claimedBonus should be set).
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General property asserted:
        // If first call did not revert then claimedBonus for recipient must have been set,
        // which implies a second call must revert. Also, if the first call succeeded then either
        // the contract's balance decreased by exactly 100 (the bonus sent) or recipient was not
        // payable/couldn't receive Ether causing a revert (but we already know it didn't revert),
        // so we assert that on success the balance decreased by 100 when recipient == this.
        if (!reverted) {
            if (recipient == address(this)) {
                assert(afterBalance + 100 == beforeBalance && secondReverted);
            } else {
                // If recipient is another address we cannot observe its balance; at minimum
                // the contract should have marked the bonus as claimed, so a second call must revert.
                assert(secondReverted);
            }
        } else {
            // If first call reverted, no further property enforced here besides reaching this assert.
            assert(reverted == true);
        }
    }

    // Accept Ether when C sends the reward to us.
    receive() external payable {}
}

