    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: recipient address and an arbitrary amount to seed the contract's reward mapping
    // Since rewardsForA is private, we cannot set it directly. We use getFirstWithdrawalBonus to add 100 to rewardsForA[recipient]
    // and then we additionally try to invoke withdrawReward(recipient) which will attempt to send the stored amount.

    // The test will: (1) call getFirstWithdrawalBonus(recipient) optionally to ensure some reward exists,
    // (2) read contract balance before and after withdrawReward, catch revert status, and finally assert
    // that if withdrawReward succeeded then contract balance decreased by the exact amount transferred and
    // that subsequent public getter for _locked is false (non-reentrancy lock reset) and that withdraw resulted
    // in rewardsForA for recipient being observable as zero via behavior: calling withdraw again must revert due to zero transfer failing
    // Because rewardsForA is private, we cannot read it; instead we assert that a successful withdraw changed address(c).balance by
    // exactly the amount externally observable as decreased and that a retry either reverts or transfers zero (no balance change).

    // To keep to constraints, we provide a single public function containing all logic and end with one assert.

    receive() external payable {}

    function run(address payable recipient, bool firstClaim) public payable {
        require(true);

        // Ensure this contract has some Ether to forward if needed
        // Note: we won't send Ether to c except via calling getFirstWithdrawalBonus which doesn't accept value

        // Optionally perform the initial claim to populate rewardsForA[recipient] with 100 and attempt withdrawal inside it
        bool initialReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            initialReverted = false;
        } catch {
            initialReverted = true;
        }

        // Read contract balance before withdraw attempt
        uint balBefore = address(c).balance;

        // Attempt withdrawReward(recipient) and detect whether it reverted
        bool withdrew;
        try c.withdrawReward(recipient) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint balAfter = address(c).balance;

        // Attempt a second withdraw to observe behavior after first withdraw (may revert or succeed with zero transfer)
        bool withdrew2;
        try c.withdrawReward(recipient) {
            withdrew2 = true;
        } catch {
            withdrew2 = false;
        }

        // General invariant to assert:
        // If the first withdraw succeeded, then contract balance decreased by exactly the difference balBefore - balAfter,
        // and a subsequent withdraw cannot transfer a positive additional amount (i.e., balAfter - address(c).balance == 0)
        // We express this by checking that if withdrew==true then balBefore >= balAfter and the second withdraw did not further decrease balance.
        // The assert uses only observable values (booleans and balances) as required.

        assert(
            // If first withdraw succeeded then it lowered or kept balance and second withdraw did not lower it further
            (withdrew == false) || (balBefore >= balAfter && balAfter <= address(c).balance)
        );
    }
}

